-- Gerado por render_sql.py. ENSAIO: nao constitui homologacao institucional.
\set ON_ERROR_STOP on
BEGIN;
DO $guard$ BEGIN
  IF inet_server_port() <> 55487 OR inet_server_addr() <> inet '127.0.0.1'
     OR current_setting('sentinela.sandbox_uuid', true) IS NULL OR current_database() <> 'sentinela_pcdf_local' THEN
    RAISE EXCEPTION 'Script restrito ao clone descartavel 127.0.0.1:55487.';
  END IF;
END $guard$;

DO $post$ BEGIN
  IF (SELECT count(*) FROM sentinela.categorias_criminais WHERE versao_catalogo='sentinela-categorias-v2-ensaio') <> 23
     OR (SELECT count(*) FROM sentinela.mapeamentos_natureza WHERE versao='pcdf-classificacao-v2-ensaio' AND status='homologado') <> 42
     OR (SELECT count(*) FROM sentinela.mapeamentos_natureza WHERE versao='pcdf-classificacao-v2-ensaio' AND status='conflitante') <> 1
     OR EXISTS (SELECT FROM sentinela.mapeamentos_natureza m JOIN sentinela.categorias_criminais c ON c.id=m.categoria_id
                WHERE m.versao='pcdf-classificacao-v2-ensaio' AND c.versao_catalogo <> 'sentinela-categorias-v2-ensaio') THEN
    RAISE EXCEPTION 'Homologacao de ensaio divergente.';
  END IF;
END $post$;
COMMIT;
